    CREATE TABLE "Products" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "ProductCode" character varying(2000) NOT NULL,
        "Barcode" character varying(2000) NOT NULL,
        "Name" character varying(2000) NOT NULL,
        "Description" character varying(2000) NOT NULL,
        "CategoryId" integer NOT NULL,
        "MeasureUnit" character varying(2000) NOT NULL,
        "MinimumStock" integer NOT NULL,
        "ShelfId" integer NOT NULL,
        "IsActive" boolean NOT NULL,
        "CreatedAt" timestamp with time zone NOT NULL,
        "UpdatedAt" timestamp with time zone NOT NULL,
        CONSTRAINT "PK_Products" PRIMARY KEY ("Id"),
        CONSTRAINT "CK_Product_Minimum" CHECK ("MinimumStock" >= 0),
        CONSTRAINT "FK_Products_Categories_CategoryId" FOREIGN KEY ("CategoryId") REFERENCES "Categories" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_Products_Shelves_ShelfId" FOREIGN KEY ("ShelfId") REFERENCES "Shelves" ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

DO $EF$
