        "BatchNumber" character varying(2000) NOT NULL,
        "Quantity" integer NOT NULL,
        "ExpiryDate" date,
        "CreatedAt" timestamp with time zone NOT NULL,
        CONSTRAINT "PK_ProductBatches" PRIMARY KEY ("Id"),
        CONSTRAINT "CK_Batch_NonNegative" CHECK ("Quantity" >= 0),
        CONSTRAINT "FK_ProductBatches_Products_ProductId" FOREIGN KEY ("ProductId") REFERENCES "Products" ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

