        "ProductId" integer NOT NULL,
        "Quantity" integer NOT NULL,
        CONSTRAINT "PK_RequestItems" PRIMARY KEY ("Id"),
        CONSTRAINT "CK_RequestItem_Positive" CHECK ("Quantity" > 0),
        CONSTRAINT "FK_RequestItems_Products_ProductId" FOREIGN KEY ("ProductId") REFERENCES "Products" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_RequestItems_Requests_RequestId" FOREIGN KEY ("RequestId") REFERENCES "Requests" ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

DO $EF$
