    CREATE TABLE "StockMovements" (
        "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
        "ProductId" integer NOT NULL,
        "Type" integer NOT NULL,
        "Quantity" integer NOT NULL,
        "PreviousStock" integer NOT NULL,
        "NextStock" integer NOT NULL,
        "UserId" uuid NOT NULL,
        "CreatedAt" timestamp with time zone NOT NULL,
        "Description" character varying(2000) NOT NULL,
        "RequestId" integer,
        "OperationId" uuid,
        CONSTRAINT "PK_StockMovements" PRIMARY KEY ("Id"),
        CONSTRAINT "CK_Movement_Balance" CHECK ("NextStock" = "PreviousStock" + "Quantity" AND "NextStock" >= 0 AND "Quantity" <> 0),
        CONSTRAINT "FK_StockMovements_Products_ProductId" FOREIGN KEY ("ProductId") REFERENCES "Products" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_StockMovements_Requests_RequestId" FOREIGN KEY ("RequestId") REFERENCES "Requests" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_StockMovements_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

